func (s OmitStruct) JSONSize() int {
	size := 42
	if s.Bio != "" {
		size += 9
		size += len(s.Bio) * 2
	}
	if s.Extra != nil {
		size += 13
		if n := len(s.Extra); n > 0 {
			size += n - 1
		}
		for i0 := range s.Extra {
			size += len(s.Extra[i0])*2 + 2
		}
	}
	if len(s.Labels) > 0 {
		size += 14
		size += len(s.Labels) * 4
		for k, v := range s.Labels {
			size += len(k) * 2
			size += len(v)*2 + 2
		}
	}
	if s.Meta != nil {
		size += 12
		size += len(s.Meta) * 4
		for k, v := range s.Meta {
			size += len(k) * 2
			size += len(v)*2 + 2
		}
	}
	size += len(s.Name) * 2
	if s.Score != 0 {
		size += 33
	}
	if len(s.Tags) > 0 {
		size += 12
		if n := len(s.Tags); n > 0 {
			size += n - 1
		}
		for i0 := range s.Tags {
			size += len(s.Tags[i0])*2 + 2
		}
	}
	return size
}

